<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetCodeVO;

trait TemplateSnippetCodeAttributeHolder
{
    protected TemplateSnippetCodeVO|string|null $code = null;
    protected bool $codeAssigned = false;

    public function getCodeOrDefault(TemplateSnippetCodeVO $code): TemplateSnippetCodeVO
    {
        if ($this->codeAssigned) {
            \assert(null !== $this->code);
            return TemplateSnippetCodeVO::from($this->code);
        } else {
            return $code;
        }
    }
    public function code(TemplateSnippetCodeVO|string $code): static
    {
        $this->code = $code;
        $this->codeAssigned = true;
        return $this;
    }
    public function getCode(): ?string
    {
        return $this->code instanceof TemplateSnippetCodeVO ? $this->code->value() : $this->code;
    }
    public function isCodeAssigned(): bool
    {
        return $this->codeAssigned;
    }
    public function writeCodeTo(mixed $att): void
    {
        if ($this->codeAssigned) {
            \assert(null !== $this->code);
            $att->code($this->code);
        }
    }
    public function readCodeFrom(mixed $att): void
    {
        if ($att->isCodeAssigned()) {
            $code = $att->getCode();
            \assert(null !== $code);
            $this->code($code);
        }
    }
    public function unsetCode(): static
    {
        $this->codeAssigned = false;
        return $this;
    }
    protected function withDefaultCode(): void
    {
    }
    protected function withAssertedCodeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->codeAssigned = $this->codeAssigned) {
            $value->code = TemplateSnippetCodeVO::tryFrom($this->code, $errorsList);
        }
    }
}
